"""Assemble SOURCES.md and DATA_GAPS.md from the per-lane fragments in data/sources and data/gaps."""
from __future__ import annotations

import json
from datetime import date

from pipeline.common.http import PROJECT_ROOT

DATA = PROJECT_ROOT / "data"


def _frags(sub: str) -> dict[str, dict]:
    out = {}
    for p in sorted((DATA / sub).glob("*.json")):
        out[p.stem] = json.loads(p.read_text())
    return out


def build_sources() -> str:
    lines = ["# SOURCES", "",
             "Generated by `python -m pipeline.build_docs` from `data/sources/*.json`. Do not edit by hand.", "",
             "Every number in the atlas traces to one of the files below. `sha256` is the hash of the file as",
             "downloaded; `local_path` is where `make data` caches it (under the git-ignored `data/raw/`).", ""]
    total = 0
    for lane, srcs in _frags("sources").items():
        lines += [f"## Lane: {lane}", "", "| source_id | dataset | publisher | vintage | retrieved | URL |", "|---|---|---|---|---|---|"]
        for sid, s in srcs.items():
            total += 1
            url = s.get("url") or ""
            lines.append(f"| `{sid}` | {s.get('dataset','')} | {s.get('publisher','')} | {s.get('vintage','')} | "
                         f"{(s.get('retrieved_at') or '')[:10]} | <{url}> |")
        lines.append("")
    lines.insert(4, f"**{total} source files** across {len(_frags('sources'))} lanes. Generated {date.today().isoformat()}.")
    lines.insert(5, "")
    return "\n".join(lines) + "\n"


def build_gaps() -> str:
    lines = ["# DATA GAPS", "",
             "Generated by `python -m pipeline.build_docs` from `data/gaps/*.json`, plus the hand-written notes in",
             "`docs/DATA_GAPS_NOTES.md`. Wherever a value below is missing, the UI shows **No data**. Nothing is estimated.", ""]
    notes = PROJECT_ROOT / "docs" / "DATA_GAPS_NOTES.md"
    if notes.exists():
        lines += [notes.read_text().strip(), ""]
    for lane, gaps in _frags("gaps").items():
        lines += [f"## Lane: {lane}", ""]
        for gid, g in gaps.items():
            scope = []
            for k in ("variables", "districts", "periods"):
                v = g.get(k)
                if v:
                    scope.append(f"{k}: {v if isinstance(v, str) else ', '.join(map(str, v))}")
            lines.append(f"- **{gid}**: {g['description']}" + (f" _Reason:_ {g['reason']}" if g.get("reason") else ""))
            if scope:
                lines.append(f"  - {'; '.join(scope)}")
        lines.append("")
    return "\n".join(lines) + "\n"


def main() -> None:
    (PROJECT_ROOT / "SOURCES.md").write_text(build_sources())
    (PROJECT_ROOT / "DATA_GAPS.md").write_text(build_gaps())
    print("wrote SOURCES.md and DATA_GAPS.md")


if __name__ == "__main__":
    main()
